// Producer: chỉ đọc -> extends
static double sum(List<? extends Number> nums) {
    double t = 0;
    for (Number n : nums) t += n.doubleValue();   // đọc: OK
    // nums.add(1);                                // lỗi biên dịch
    nums.add(null);                                // hợp lệ duy nhất
    return t;
}

// Consumer: ghi vào -> super
static void fill(List<? super Integer> dest) {
    dest.add(1);                  // ghi Integer: OK
    // Integer x = dest.get(0);   // lỗi: chỉ đảm bảo Object
    Object o = dest.get(0);
}

